<?php
require_once dirname(__DIR__) . '/middleware/bootstrap.php';
require_role('admin');
$db=Database::connection();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');
 try{
  if($action==='department_add'){
   $code=strtoupper(post_string('code',20));$name=post_string('name',120);
   if(!preg_match('/^[A-Z0-9_-]{2,20}$/',$code)||strlen($name)<2)throw new DomainException('Enter a valid department code and name.');
   $db->prepare('INSERT INTO departments(code,name) VALUES(?,?)')->execute([$code,$name]);
   flash('success','Department added.');
  }elseif($action==='department_toggle'){
   $db->prepare('UPDATE departments SET active=? WHERE id=?')->execute([(int)($_POST['active']??0),(int)($_POST['id']??0)]);
   flash('success','Department status updated.');
  }elseif($action==='term_save'){
   $id=(int)($_POST['id']??0);$name=post_string('term_name',100);$year=post_string('academic_year',20);$semester=(int)($_POST['semester']??0);$start=post_string('starts_on',10);$end=post_string('ends_on',10);$regStart=post_string('registration_starts_at',16);$regEnd=post_string('registration_ends_at',16);$limit=(int)($_POST['credit_limit']??0);
   if(strlen($name)<2||!preg_match('/^\d{4}-\d{4}$/',$year)||$semester<1||$semester>12||$start>$end||$regStart>=$regEnd||$limit<1||$limit>60)throw new DomainException('Check the term name, dates, semester, and credit limit.');
   $db->beginTransaction();
   if(!empty($_POST['is_current']))$db->exec('UPDATE academic_terms SET is_current=0');
   if($id){$stmt=$db->prepare('UPDATE academic_terms SET name=?,academic_year=?,semester=?,starts_on=?,ends_on=?,registration_starts_at=?,registration_ends_at=?,credit_limit=?,is_current=? WHERE id=?');$stmt->execute([$name,$year,$semester,$start,$end,str_replace('T',' ',$regStart).':00',str_replace('T',' ',$regEnd).':00',$limit,!empty($_POST['is_current'])?1:0,$id]);}
   else{$stmt=$db->prepare('INSERT INTO academic_terms(name,academic_year,semester,starts_on,ends_on,registration_starts_at,registration_ends_at,credit_limit,is_current) VALUES(?,?,?,?,?,?,?,?,?)');$stmt->execute([$name,$year,$semester,$start,$end,str_replace('T',' ',$regStart).':00',str_replace('T',' ',$regEnd).':00',$limit,!empty($_POST['is_current'])?1:0]);}
   $db->commit();flash('success','Academic term saved.');
  }elseif($action==='term_current'){
   $db->beginTransaction();$db->exec('UPDATE academic_terms SET is_current=0');$db->prepare('UPDATE academic_terms SET is_current=1 WHERE id=?')->execute([(int)$_POST['id']]);$db->commit();flash('success','Current term changed.');
  }
  redirect('admin/settings.php');
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();if(!$e instanceof DomainException&&!($e instanceof PDOException&&(string)$e->getCode()==='23000'))error_log('Admin settings error: '.$e->getMessage());$error=$e instanceof DomainException?$e->getMessage():($e instanceof PDOException&&(string)$e->getCode()==='23000'?'That department code or term already exists.':'The change could not be saved. Check the values and try again.');}
}
$departments=$db->query('SELECT * FROM departments ORDER BY name')->fetchAll();$terms=$db->query('SELECT * FROM academic_terms ORDER BY starts_on DESC')->fetchAll();$editId=(int)($_GET['edit_term']??0);$editing=null;foreach($terms as $term){if((int)$term['id']===$editId)$editing=$term;}
page_start('Departments and terms','admin/settings.php');
?>
<div class="content-width"><?php page_title('Departments & academic terms','Maintain student departments and registration windows.'); ?><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?>
<div class="row g-4"><div class="col-lg-5"><div class="panel mb-4"><h2 class="h5 fw-bold">Add department</h2><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="department_add"><div class="mb-3"><label class="form-label">Code</label><input class="form-control" name="code" maxlength="20" required placeholder="BIO"></div><div class="mb-3"><label class="form-label">Department name</label><input class="form-control" name="name" maxlength="120" required></div><button class="btn btn-primary">Add department</button></form></div>
<div class="panel p-0 overflow-hidden"><div class="p-3"><h2 class="h5 fw-bold mb-0">Departments</h2></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Department</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($departments as $d): ?><tr><td><strong><?= e($d['code']) ?></strong><div class="small"><?= e($d['name']) ?></div></td><td><span class="badge text-bg-<?= $d['active']?'success':'secondary' ?>"><?= $d['active']?'Active':'Inactive' ?></span></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="department_toggle"><input type="hidden" name="id" value="<?= (int)$d['id'] ?>"><input type="hidden" name="active" value="<?= $d['active']?0:1 ?>"><button class="btn btn-sm btn-outline-secondary"><?= $d['active']?'Disable':'Enable' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<div class="col-lg-7"><div class="panel mb-4"><h2 class="h5 fw-bold"><?= $editing?'Edit academic term':'Add academic term' ?></h2><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="term_save"><input type="hidden" name="id" value="<?= (int)($editing['id']??0) ?>"><div class="row g-3"><div class="col-md-7"><label class="form-label">Term name</label><input class="form-control" name="term_name" required maxlength="100" value="<?= e($editing['name']??'') ?>"></div><div class="col-md-5"><label class="form-label">Academic year</label><input class="form-control" name="academic_year" required placeholder="2026-2027" value="<?= e($editing['academic_year']??'') ?>"></div><div class="col-md-4"><label class="form-label">Semester</label><input class="form-control" type="number" name="semester" min="1" max="12" value="<?= e($editing['semester']??1) ?>"></div><div class="col-md-4"><label class="form-label">Credit limit</label><input class="form-control" type="number" name="credit_limit" min="1" max="60" value="<?= e($editing['credit_limit']??24) ?>"></div><div class="col-md-4 d-flex align-items-end pb-2"><div class="form-check"><input class="form-check-input" type="checkbox" name="is_current" id="isCurrent" <?= !empty($editing['is_current'])?'checked':'' ?>><label class="form-check-label" for="isCurrent">Make current</label></div></div><div class="col-md-6"><label class="form-label">Term begins</label><input class="form-control" type="date" name="starts_on" required value="<?= e($editing['starts_on']??'') ?>"></div><div class="col-md-6"><label class="form-label">Term ends</label><input class="form-control" type="date" name="ends_on" required value="<?= e($editing['ends_on']??'') ?>"></div><div class="col-md-6"><label class="form-label">Registration opens</label><input class="form-control" type="datetime-local" name="registration_starts_at" required value="<?= e(isset($editing['registration_starts_at'])?date('Y-m-d\TH:i',strtotime($editing['registration_starts_at'])):'') ?>"></div><div class="col-md-6"><label class="form-label">Registration deadline</label><input class="form-control" type="datetime-local" name="registration_ends_at" required value="<?= e(isset($editing['registration_ends_at'])?date('Y-m-d\TH:i',strtotime($editing['registration_ends_at'])):'') ?>"></div></div><button class="btn btn-primary mt-3"><?= $editing?'Save term':'Add term' ?></button><?php if($editing): ?> <a class="btn btn-light mt-3" href="<?= e(url('admin/settings.php')) ?>">Cancel edit</a><?php endif; ?></form></div>
<div class="panel p-0 overflow-hidden"><div class="p-3"><h2 class="h5 fw-bold mb-0">Academic terms</h2></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Term</th><th>Registration period</th><th>Credits</th><th>Current</th><th></th></tr></thead><tbody><?php foreach($terms as $t): ?><tr><td><?= e($t['name']) ?><div class="small text-muted"><?= e($t['academic_year']) ?> · Semester <?= (int)$t['semester'] ?></div></td><td class="small"><?= e(date('M j, Y',strtotime($t['registration_starts_at']))) ?> – <?= e(date('M j, Y',strtotime($t['registration_ends_at']))) ?></td><td><?= (int)$t['credit_limit'] ?></td><td><?= $t['is_current']?'<span class="badge text-bg-success">Current</span>':'—' ?></td><td class="table-actions"><a class="btn btn-sm btn-outline-primary" href="<?= e(url('admin/settings.php?edit_term='.(int)$t['id'])) ?>">Edit</a><?php if(!$t['is_current']): ?><form class="d-inline" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="term_current"><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><button class="btn btn-sm btn-outline-secondary">Set current</button></form><?php endif; ?></td></tr><?php endforeach; if(!$terms): ?><tr><td colspan="5" class="text-muted">No academic terms.</td></tr><?php endif; ?></tbody></table></div></div></div></div></div>
<?php page_end(); ?>
